--
-- Name: nexik_semantic_search(uuid, public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: netnext
--

CREATE FUNCTION public.nexik_semantic_search(p_org_id uuid, p_query_embedding public.vector, p_limit integer DEFAULT 5, p_min_similarity double precision DEFAULT 0.5) RETURNS TABLE(chunk_id uuid, document_id uuid, content text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    c.id as chunk_id,
    c.doc_id as document_id,
    c.content,
    c.metadata,
    1 - (c.embedding <=> p_query_embedding) as similarity
  FROM nexik_knowledge_chunks c
  JOIN nexik_knowledge_docs d ON d.id = c.doc_id
  WHERE d.org_id = p_org_id
    AND c.embedding IS NOT NULL
    AND 1 - (c.embedding <=> p_query_embedding) >= p_min_similarity
  ORDER BY c.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$$;


