callback-btn *:before,\\n    .callback-btn *:after {\\n        font-family: var(--ff-base);\\n        margin: 0;\\n        padding: 0;\\n        box-sizing: border-box;\\n    }\\n    .callback-btn {\\n        background: transparent;\\n        border: none;\\n        outline: none;\\n        cursor: pointer;\\n        width: var(--s-handset-pulse);\\n        height: var(--s-handset-pulse);\\n        position: fixed;\\n        bottom: 20px;\\n        left: 18%;\\n        transform: translateX(-50%);\\n        display: block;\\n        padding: 12px;\\n        z-index: var(--z-callback-btn);\\n        text-decoration: none;\\n    }\\n    .callback-btn:before,\\n    .callback-btn:after {\\n        content: '';\\n        display: block;\\n        border-radius: 50%;\\n        position: absolute;\\n        opacity: 0;\\n    }\\n    .callback-btn:before {\\n        background: var(--bg-shadow-green);\\n        width: var(--s-handset-pulse-small);\\n        height: var(--s-handset-pulse-small);\\n        transform: scale(0.5);\\n        top: 50%;\\n        left: 50%;\\n        margin-left: calc(var(--s-handset-pulse-small) / -2);\\n        margin-top: calc(var(--s-handset-pulse-small) / -2);\\n        animation: pulse-small 3s ease-in-out infinite;\\n    }\\n    .callback-btn:after {\\n        background: transparent;\\n        width: var(--s-handset-pulse);\\n        height: var(--s-handset-pulse);\\n        top: 0;\\n        left: 0;\\n        transform: scale(0.6);\\n        border: 3px solid var(--bg-handset-green);\\n        animation: pulse 3s ease-in-out infinite;\\n    }\\n    .callback-btn__circle {\\n        width: var(--s-handset-circle);\\n        height: var(--s-handset-circle);\\n        background: var(--bg-handset-green);\\n        display: block;\\n        position: relative;\\n        padding: 5px;\\n        border-radius: 50%;\\n        transition: box-shadow .25s ease-in-out;\\n        z-index: var(--z-callback-btn);\\n    }\\n    .callback-btn__icon {\\n        display: block;\\n        background: var(--bg-handset-green);\\n        width: var(--s-handset-circle-sm);\\n        height: var(--s-handset-circle-sm);\\n        border-radius: 50%;\\n        position: relative;\\n        transition: box-shadow .25s ease-in-out;\\n    }\\n    .callback-btn__icon:before {\\n        content: '';\\n        display: block;\\n        width: var(--s-handset-icon);\\n        height: var(--s-handset-icon);\\n        position: absolute;\\n        top: 50%;\\n        left: 50%;\\n        margin-left: calc(var(--s-handset-icon) / -2);\\n        margin-top: calc(var(--s-handset-icon) / -2);\\n        background-image: url('/assets/images/img/phone.png');\\n        background-size: contain;\\n        background-repeat: no-repeat;\\n        background-position: center;\\n    }\\n    .callback-btn:active .callback-btn__circle {\\n        transform: scale(0.95);\\n        transition: transform 0.1s ease;\\n    }\\n    @keyframes pulse-small {\\n        0% { opacity: 0; transform: scale(0.5); }\\n        50% { opacity: 1; transform: scale(1); }\\n        95% { opacity: 0; transform: scale(1); }\\n        100% { opacity: 0; transform: scale(0.5); }\\n    }\\n    @keyframes pulse {\\n        0% { opacity: 0; transform: scale(0.6); }\\n        50% { opacity: 1; transform: scale(1); }\\n        100% { opacity: 0; transform: scale(1.2); }\\n    }\\n}\\n@media (min-width: 769px){.callback-btn {display: none !important;}}\\n</style>\\n<a href=\\"#\\" class=\\"callback-btn\\" id=\\"callbackBtn\\" style=\\"color: rgb(255, 255, 255); background-color: rgba(0, 0, 0, 0); background: rgba(0, 0, 0, 0) none repeat scroll 0% 0% / auto padding-box border-box; font-family: &quot;Avenir Next Cyr&quot;, sans-serif; font-size: 20px; font-weight: 400; line-height: 26px; text-align: start; padding: 0px; margin: 0px; border: 0px none rgb(255, 255, 255); border-radius: 0px; min-width: 0px; min-height: 0px; flex-direction: row; position: static; opacity: 1\\">\\n